#include <iostream>
#include <string>

bool estMajeur(int age) {
    return age >= 18;
}

void saluer(std::string nom, int age) {
    if (estMajeur(age)) {
        std::cout << "Bonjour " << nom << "\n";
    } else {
        std::cout << "Salut " << nom << "\n";
    }
}

int main() {
    saluer("Afi", 17);
    saluer("Kossi", 25);
    return 0;
}

