#include <iostream>
#include <string>

std::string mention(int note) {
    if (note >= 16) {
        return "Très bien";
    } else if (note >= 14) {
        return "Bien";
    } else if (note >= 12) {
        return "Assez bien";
    } else if (note >= 10) {
        return "Passable";
    }
    return "Insuffisant";
}

int main() {
    int note;
    std::cin >> note;
    std::cout << "Note " << note << " : " << mention(note) << "\n";
    return 0;
}

