#include <iostream>

int sousTotal(int prix, int quantite) {
    return prix * quantite;
}

int tva(int montant) {
    return montant * 18 / 100;
}

int totalTTC(int prix, int quantite) {
    int base = sousTotal(prix, quantite);
    return base + tva(base);
}

int main() {
    int prix, quantite;
    std::cin >> prix >> quantite;
    int base = sousTotal(prix, quantite);
    std::cout << "Sous-total : " << base << " FCFA\n";
    std::cout << "TVA : " << tva(base) << " FCFA\n";
    std::cout << "Total : " << totalTTC(prix, quantite) << " FCFA\n";
    return 0;
}
